// Coverage collection and potential plateau detection mechanisms

// Coverage collection modes
enum class CoverageMode {
  kBestEffort,          // Best effort coverage (doesn't reset counters)
  kPreciseCount,        // Precise count coverage (resets counters)
  kPreciseBinary,       // Precise binary coverage (resets for incremental updates)
  kBlockCount,          // Block count coverage
  kBlockBinary,         // Block binary coverage
};

// Coverage collection implementation
std::unique_ptr<Coverage> Coverage::CollectPrecise(Isolate* isolate) {
  DCHECK(!isolate->is_best_effort_code_coverage());
  std::unique_ptr<Coverage> result =
      Collect(isolate, isolate->code_coverage_mode());

  // Reset feedback vectors list after reporting coverage
  if (isolate->is_precise_binary_code_coverage() ||
      isolate->is_block_binary_code_coverage()) {
    isolate->SetFeedbackVectorsForProfilingTools(
        ReadOnlyRoots(isolate).empty_array_list());
  }
  return result;
}

// Coverage affects optimization decisions
class SharedFunctionInfo : public TorqueGeneratedSharedFunctionInfo<SharedFunctionInfo, HeapObject> {
 public:
  // Indicates that the function has been reported for binary code coverage
  DECL_BOOLEAN_ACCESSORS(has_reported_binary_coverage)

  // When collecting binary coverage, reset this flag to avoid optimizing
  // functions before they have reported coverage
  inline bool ShouldDelayOptimizationDueToCoverage(Isolate* isolate) const {
    if (isolate->is_precise_binary_code_coverage() &&
        !has_reported_binary_coverage()) {
      return true;  // Delay optimization until coverage is reported
    }
    return false;
  }
};

// Coverage collection resets invocation counts
void CollectAndMaybeResetCounts(Isolate* isolate,
                                SharedToCounterMap* counter_map,
                                v8::debug::CoverageMode coverage_mode) {
  const bool reset_count =
      coverage_mode != v8::debug::CoverageMode::kBestEffort;

  switch (isolate->code_coverage_mode()) {
    case v8::debug::CoverageMode::kBlockBinary:
    case v8::debug::CoverageMode::kBlockCount:
    case v8::debug::CoverageMode::kPreciseBinary:
    case v8::debug::CoverageMode::kPreciseCount: {
      // Feedback vectors are already listed to prevent losing them to GC
      auto list = Cast<ArrayList>(
          isolate->factory()->feedback_vectors_for_profiling_tools());
      for (int i = 0; i < list->length(); i++) {
        Tagged<FeedbackVector> vector = Cast<FeedbackVector>(list->get(i));
        Tagged<SharedFunctionInfo> shared = vector->shared_function_info();
        DCHECK(shared->IsSubjectToDebugging());
        uint32_t count = static_cast<uint32_t>(vector->invocation_count());
        if (reset_count) vector->clear_invocation_count(kRelaxedStore);
        counter_map->Add(shared, count);
      }
      break;
    }
    case v8::debug::CoverageMode::kBestEffort: {
      // Iterate heap to collect best-effort coverage
      HeapObjectIterator heap_iterator(isolate->heap());
      for (Tagged<HeapObject> current_obj = heap_iterator.Next();
           !current_obj.is_null(); current_obj = heap_iterator.Next()) {
        if (!IsJSFunction(current_obj)) continue;
        Tagged<JSFunction> func = Cast<JSFunction>(current_obj);
        Tagged<SharedFunctionInfo> shared = func->shared();
        if (!shared->IsSubjectToDebugging()) continue;

        uint32_t count = 0;
        if (func->has_feedback_vector()) {
          count = static_cast<uint32_t>(
              func->feedback_vector()->invocation_count());
        } else if (func->shared()->HasBytecodeArray() &&
                   func->raw_feedback_cell()->interrupt_budget() <
                       TieringManager::InterruptBudgetFor(isolate, func, {})) {
          // We haven't allocated feedback vector, but executed the function
          // at least once. We don't have precise invocation count here.
          count = 1;
        }
        counter_map->Add(shared, count);
      }
      break;
    }
  }
}

// Potential plateau detection patterns (not explicitly named "plateau" but similar concepts):

// 1. IC stability detection - if ICs keep changing, delay optimization
bool ShouldResetInterruptBudgetByICChange(
    CachedTieringDecision cached_tiering_decision) {
  switch (cached_tiering_decision) {
    case CachedTieringDecision::kEarlyMaglev:
    case CachedTieringDecision::kEarlyTurbofan:
      return false;  // Don't reset - optimize early
    case CachedTieringDecision::kPending:
    case CachedTieringDecision::kEarlySparkplug:
    case CachedTieringDecision::kDelayMaglev:
    case CachedTieringDecision::kNormal:
      return true;   // Reset budget - wait for stabilization
  }
}

// 2. Invocation count plateau - if function is called many times but
//    doesn't trigger optimization due to IC changes
void TieringManager::NotifyICChanged(Tagged<FeedbackVector> vector) {
  // When ICs change, we increase the interrupt budget, effectively
  // creating a plateau where the function keeps executing but doesn't
  // tier up until ICs stabilize
  if (new_budget > current_budget) {
    vector->set_interrupt_budget_reset_by_ic_change(true);
    cell->set_interrupt_budget(new_budget);
  }
}

// 3. Coverage reporting as a form of plateau detection
//    Functions won't optimize until they've reported coverage
//    This creates a deliberate plateau for coverage collection
